// === Tab: mySketch ===

let colors = [ "#000000", "#FF0000", "#0000FF",  "#00b2b4", "#00FF00" ]

const branchingFactor = 0.025;
const noiseFactor = 5;
const agentArray = [];
const agentSpeed = 100;

let world;

//=====

function setup() { init() }

function init() {
  createCanvas(windowWidth, windowHeight);

	background(255);
	noFill();

	incr_heading = PI/3;

  world = array2d();		// init array width * height <= value false

  agentArray.length = 0;

	for ( let i = 0; i < 5; i++) { agentArray.push(agent(i%5)) }

	frameRate(60);	
}

//===

mouseClicked = () => init();

//=====

function draw() {

	let agent_j;

  for (let i = 0; i < agentSpeed; i++) {
		for ( let j = 0; j < agentArray.length; j++ ) {
			agent_j = agentArray[j];
			agent_j.next();
		}	
  }
}

//=====

function* agent(i) {

	let margin, X, Y, heading, colour, newX, newY, stack, numb_pt;

	margin = 50;

  X = random(margin, width - margin);
  Y = random(margin, height - margin);

  heading = incr_heading;
	colour = colors[i];

  stack = [{ X, Y, heading }];
  world.set( X, Y, colour);

  while (stack.length) {

    let { X, Y, heading } = stack.pop();

    let num;
		if ( random() < branchingFactor ) { numb_pt = 2 }
		else															{ numb_pt = 1 }

    for (i = 0; i < numb_pt; i++, heading += incr_heading) {

    	newX = X;
      newY = Y;

      do {
        n = noise(newX / width, newY / height) * noiseFactor;
        newX = (newX + cos(heading + n) + width) % width;
        newY = (newY + sin(heading + n) + height) % height;
      } while (floor(newX) === floor(X) && floor(newY) === floor(Y));

      if (!world.canMoveTo(newX, newY)) continue;											// is x,y used. If yes leave FOR loop

      stack.push({ X: newX, Y: newY, heading });
      world.set(newX, newY, colour);																	// in world x,y used

    }	//

		yield;		
  }
}

//=====

function array2d() {
  const array = Array.from({ length: width }, () => Array(height).fill(false));

  return {
    canMoveTo: (x, y) => { return array[floor(x)][floor(y)] === false },
    set: (x, y, colour) => { array[floor(x)][floor(y)] = true ; stroke (colour); rect (x, y, 1.0) },
  };
}
